class CustomStack {
    vector<int> st;
    vector<int> inc;
    int sz;
    int cap;
public:
    CustomStack(int maxSize) {
        cap = maxSize;
        sz = 0;
        st.resize(maxSize);
        inc.resize(maxSize, 0);
    }

    void push(int x) {
        if (sz < cap) {
            st[sz] = x;
            inc[sz] = 0;
            sz++;
        }
    }

    int pop() {
        if (sz == 0) return -1;
        int i = sz - 1;
        int res = st[i] + inc[i];
        if (i > 0) inc[i - 1] += inc[i];
        inc[i] = 0;
        sz--;
        return res;
    }

    void increment(int k, int val) {
        if (sz == 0) return;
        int idx = (k < sz ? k : sz) - 1;
        if (idx >= 0) inc[idx] += val;
    }
};
